{
  "relationship": {
    "statement": "A decision tree classifies data by recursively splitting samples on feature thresholds (x <= t) that separate classes. At each node, it chooses the threshold minimizing weighted Gini impurity so child branches become as pure as possible.",
    "formula": "G_w = \\frac{n_L}{N}G_L + \\frac{n_R}{N}G_R",
    "assumptions": [
      "Each decision node evaluates a single axis-aligned threshold x <= t.",
      "The dataset contains a fixed number of samples across two classes.",
      "Impurity is measured with binary Gini impurity G = 1 - pA^2 - pB^2."
    ]
  },
  "quantities": [
    {
      "id": "threshold",
      "label": "Split threshold t",
      "unit": "",
      "role": "control",
      "meaning": "Cutoff value on feature x sending samples left (x <= t) or right (x > t)."
    },
    {
      "id": "separation",
      "label": "Class separation",
      "unit": "",
      "role": "control",
      "meaning": "Distance between the two class centers along feature x."
    },
    {
      "id": "spread",
      "label": "Feature spread",
      "unit": "",
      "role": "control",
      "meaning": "Within-class scatter of samples around each class center."
    },
    {
      "id": "sample_count",
      "label": "Total samples N",
      "unit": "pts",
      "role": "fixed",
      "meaning": "Fixed total number of labeled samples evaluated at the root node."
    },
    {
      "id": "parent_gini",
      "label": "Parent Gini",
      "unit": "",
      "role": "result",
      "meaning": "Gini impurity of the combined dataset before splitting."
    },
    {
      "id": "left_gini",
      "label": "Left branch Gini",
      "unit": "",
      "role": "result",
      "meaning": "Gini impurity of samples routed to the left child (x <= t)."
    },
    {
      "id": "right_gini",
      "label": "Right branch Gini",
      "unit": "",
      "role": "result",
      "meaning": "Gini impurity of samples routed to the right child (x > t)."
    },
    {
      "id": "weighted_gini",
      "label": "Weighted split Gini",
      "unit": "",
      "role": "result",
      "meaning": "Sample-weighted average Gini impurity across both child branches."
    },
    {
      "id": "gini_gain",
      "label": "Impurity reduction",
      "unit": "",
      "role": "result",
      "meaning": "Decrease in Gini impurity achieved by splitting at threshold t."
    },
    {
      "id": "accuracy",
      "label": "Split accuracy",
      "unit": "%",
      "role": "result",
      "meaning": "Percentage of samples correctly classified by leaf majority votes."
    }
  ]
}

